<template><div class="page-shell narrow-page"><header class="page-header compact"><div><h1>歌手工作台</h1><p class="page-subtitle">上传音频并创建歌曲草稿。</p></div><router-link class="secondary-button" to="/artist/profile"><UserRound :size="18"/><span>歌手资料</span></router-link></header><form class="editor-form" @submit.prevent="create"><label>歌曲名称<input v-model.trim="form.title" maxlength="200" required></label><label>时长（秒）<input v-model.number="form.durationSeconds" type="number" min="1" required></label><label>音频文件<input ref="audio" type="file" accept="audio/*" required @change="pick('audio',$event)"><small>必填，文件类型和内容由 Media 服务校验。</small></label><label>封面图片<input type="file" accept="image/*" @change="pick('cover',$event)"><small>可选。</small></label><label>歌词文件<input type="file" accept=".lrc,text/plain" @change="pick('lyrics',$event)"><small>可选，支持 LRC。</small></label><p v-if="message" :class="success?'form-success':'form-error'" role="status">{{message}}</p><button class="primary-button" type="submit" :disabled="submitting"><Upload :size="18"/><span>{{submitting?'上传中…':'创建草稿'}}</span></button></form><section v-if="draft" class="draft-result"><div><span class="status-text">{{statusLabel}}</span><h2>{{draft.title}}</h2><p>草稿 #{{draft.id}}</p></div><div class="draft-actions"><button class="secondary-button" type="button" @click="update"><Save :size="18"/><span>保存修改</span></button><button class="primary-button" type="button" :disabled="draft.status!=='DRAFT'" @click="submitDraft"><Send :size="18"/><span>提交审核</span></button></div></section></div></template>
<script>
import {Save,Send,Upload,UserRound} from 'lucide-vue'; import {artistStudio} from '../artist/client.js'; import {draftStatusLabel,preserveStudioForm} from '../artist/studio-model.js'; import {problemMessage} from '../ui/problem-message.js';
export default{name:'ArtistStudioView',components:{Save,Send,Upload,UserRound},data:()=>({form:{title:'',durationSeconds:180,audio:null,cover:null,lyrics:null},draft:null,submitting:false,success:false,message:''}),computed:{statusLabel(){return draftStatusLabel(this.draft?.status);}},methods:{pick(field,event){this.form[field]=event.target.files?.[0]||null;},payload(){return{title:this.form.title,durationMs:Math.round(Number(this.form.durationSeconds)*1000),mediaObjectId:this.draft.mediaObjectId,coverMediaObjectId:this.draft.coverMediaObjectId??null,lyricsMediaObjectId:this.draft.lyricsMediaObjectId??null};},async create(){this.submitting=true;this.message='';try{this.draft=await artistStudio.createDraft({title:this.form.title,durationMs:Math.round(Number(this.form.durationSeconds)*1000),audio:this.form.audio,cover:this.form.cover,lyrics:this.form.lyrics});this.success=true;this.message='草稿已创建。';}catch(problem){this.form=preserveStudioForm(this.form,problem);this.success=false;this.message=problemMessage(problem);}finally{this.submitting=false;}},async update(){try{this.draft=await artistStudio.updateDraft(this.draft.id,this.payload());this.success=true;this.message='草稿已保存。';}catch(problem){this.success=false;this.message=problemMessage(problem);}},async submitDraft(){try{this.draft=await artistStudio.submit(this.draft.id);this.success=true;this.message='歌曲已提交审核。';}catch(problem){this.success=false;this.message=problemMessage(problem);}}}};
</script>
